-- KA EMLAK: 27 ilanın İngilizce ve Farsça çevirilerini ekler.
-- Supabase SQL Editor'a yapıştırıp bir kez çalıştırın. Yeniden çalıştırmak zarar vermez.
-- Panelde elle düzeltilmiş bir çeviri (auto: false) varsa o dile dokunulmaz.
update public.listings l
set data = jsonb_set(l.data, '{translations}', coalesce(l.data->'translations', '{}'::jsonb) || coalesce((
      select jsonb_object_agg(e.key, e.value) from jsonb_each(t.translations) e
      where coalesce(l.data#>>array['translations', e.key, 'auto'], 'true') <> 'false'
    ), '{}'::jsonb), true),
    updated_at = now()
from (select d->>'id' as id, d->'translations' as translations from jsonb_array_elements($ka$[{"id":"f42a14d3-6ba8-4a2c-af92-84e0848b55e3","translations":{"en":{"title":"Kepez Baraj 1+1 apartment for sale","description":"Spacious 1+1 Apartment for Sale in Kepez Baraj Mahallesi\nNet 50 m² | Gross 70 m²\n2.900.000 TL\n\n(Previous price: 4.000.000 TL)\n\nA 1+1 apartment in a gated complex in Kepez Baraj Mahallesi, with a pool view and a wide, unobstructed view.\n\nApartment Features\n\nNet 50 m², gross 70 m²\n\n1+1 (enclosed built-in kitchen)\n\nFloor: ground-floor apartment\n\nFacade: South + East + North\n\nView: Pool + wide city view\n\nNatural gas (combi boiler) + air-conditioning installation in all rooms\n\nRadiator heating installed\n\nHilton-style bathroom + shower cabin\n\nUnfurnished, ready to move in immediately\n\nComplex Facilities\n\n1.900 m² plot, 2 blocks, 24 apartments\n\nOutdoor swimming pool\n\nGazebo and landscaping\n\nOutdoor parking\n\nElevator accessible for people with disabilities\n\nFiber internet infrastructure\n\nConstruction is 90% complete. All works will be finished and the occupancy permit application will be submitted in about 2 months.\n\nLocation Advantages\n\nSchool → 500 m\n\nSupermarket & shopping mall → 500 m\n\nKepez State Hospital → 1,5 km\n\nAirport → 8 km\n\nCity centre → 8 km\n\nSwap Option\nA swap is possible for original, low-mileage Toyota or Honda vehicles. (Our 1+1 apartment is also available.)\n\nWrite to us for details and an on-site viewing.","features":["Air conditioning"],"auto":true,"sourceHash":"beafd5f539417b6e"},"fa":{"title":"آپارتمان 1+1 برای فروش در کپز باراژ","description":"آپارتمان 1+1 بزرگ برای فروش در محله کپز باراژ\nمتراژ خالص 50 m² | ناخالص 70 m²\n2.900.000 TL\n\n(قیمت قبلی: 4.000.000 TL)\n\nآپارتمان 1+1 داخل مجتمع مسکونی در محله کپز باراژ، با منظره استخر و منظره وسیع و بدون مانع.\n\nویژگی‌های آپارتمان\n\nخالص 50 m²، ناخالص 70 m²\n\n1+1 (آشپزخانه بسته با وسایل توکار)\n\nطبقه: همکف\n\nنما: جنوب + شرق + شمال\n\nمنظره: استخر + منظره وسیع شهر\n\nگاز طبیعی (پکیج) + سیستم کولر برای همه اتاق‌ها\n\nلوله‌کشی شوفاژ انجام شده\n\nحمام هیلتون + کابین دوش\n\nبدون مبلمان، آماده برای نقل‌مکان فوری\n\nامکانات مجتمع\n\nزمین 1.900 m²، 2 بلوک، 24 واحد\n\nاستخر روباز\n\nآلاچیق و فضای سبز\n\nپارکینگ روباز\n\nآسانسور مناسب معلولان\n\nزیرساخت اینترنت فیبر\n\nساخت‌وساز 90% تکمیل شده است. حدود 2 ماه دیگر تمام کارها به پایان می‌رسد و برای پایان‌کار اقدام خواهد شد.\n\nمزایای موقعیت\n\nمدرسه ← 500 m\n\nسوپرمارکت و مرکز خرید ← 500 m\n\nبیمارستان دولتی کپز ← 1,5 km\n\nفرودگاه ← 8 km\n\nمرکز شهر ← 8 km\n\nگزینه معاوضه\nامکان معاوضه با خودروهای اصل و کم‌کارکرد تویوتا یا هوندا وجود دارد. (آپارتمان 1+1 ما نیز موجود است)\n\nبرای جزئیات و بازدید حضوری پیام بدهید.","features":["کولر"],"auto":true,"sourceHash":"beafd5f539417b6e"}}},{"id":"5b5aa712-dc0b-4862-9b31-3fecc77e9c84","translations":{"en":{"title":"Daily rental 4+1 detached villa with garden in Duacı","description":"🌿 4+1 DETACHED VILLA IN DUACI, ANTALYA\n\nIdeal for a peaceful, comfortable holiday in the midst of nature with your family and loved ones.\n\n📍 Antalya / Kepez / Duacı\n\n🏡 4+1 detached villa\n\n📐 200 m² net – 250 m² gross\n\n🌿 300 m² outdoor area\n\n👨‍👩‍👧‍👦 Accommodates up to 8-10 people\n\nVILLA FEATURES\n\n• Spacious, airy living room\n\n• Comfortable bedrooms\n\n• Fully equipped kitchen\n\n• Built-in set, refrigerator and dishwasher\n\n• Modern, spacious bathrooms\n\n• Air conditioning in all rooms\n\n• High-speed Wi-Fi\n\n• TV\n\n• Bed linen and towel service\n\n• Professional cleaning\n\n🌿 OUTDOOR AREA\n\n• Private, sheltered garden\n\n• Large veranda\n\n• Barbecue area\n\n• Garden furniture\n\n• Private parking\n\n• Quiet location in the midst of nature\n\n📍 LOCATION ADVANTAGE\n\nLocated in the quiet, nature-filled atmosphere of Duacı, our villa is well placed for access to Antalya city centre, shopping areas and beaches.\n\n📋 RENTAL INFORMATION\n\n🕑 Check-in: 14:00\n\n🕚 Check-out: 11:00\n\n• Identity notification is made through the KBS (Accommodation Notification System) for all guests staying.\n\n• Pets are not accepted.\n\n• Not suitable for parties and events.\n\n• Prices may vary depending on the season, holiday periods and length of stay.\n\nA Tourism Residential Rental Permit is available.\n\n📞 Reservations & Information:\n\nİshak Kahraman – KA GLOBAL İNŞAAT EMLAK\n\n0532 224 76 58\n\nYou can contact us for current prices, availability and reservations.\n\nKA GLOBAL SHORT TERM RENTALS\n\n🏡 Daily • Weekly • Monthly Accommodation\n\n📍 Antalya / Türkiye\n\n🌍 Türkçe • English • فارسی\n\nWe serve you with the KA GLOBAL assurance for reliable, comfortable and select short-term accommodation options in Antalya.\n\n🏠 Villa • Apartment • Residence\n\n🌊 Options close to the sea\n\n🏊 Alternatives with pools and in gated complexes\n\n📅 Daily • Weekly • Monthly rental\n\n📞 Contact us for detailed information and reservations.\n\nKA GLOBAL Real Estate & Construction\n\nAntalya","features":["Furnished","Natural gas","Combi boiler"],"auto":true,"sourceHash":"e3ebbb1d7cd93b14"},"fa":{"title":"ویلای مستقل 4+1 با باغ برای اجاره روزانه در دواجی","description":"🌿 ویلای مستقل 4+1 در دواجی آنتالیا\n\nمناسب برای یک تعطیلات آرام و راحت در دل طبیعت همراه خانواده و عزیزانتان.\n\n📍 آنتالیا / کپز / دواجی\n\n🏡 ویلای مستقل 4+1\n\n📐 200 m² خالص – 250 m² ناخالص\n\n🌿 300 m² فضای باز\n\n👨‍👩‍👧‍👦 اقامت تا 8-10 نفر\n\nویژگی‌های ویلا\n\n• سالن بزرگ و جادار\n\n• اتاق‌خواب‌های راحت\n\n• آشپزخانه کاملاً مجهز\n\n• وسایل توکار، یخچال و ماشین ظرفشویی\n\n• حمام‌های مدرن و بزرگ\n\n• کولر در همه اتاق‌ها\n\n• وای‌فای پرسرعت\n\n• تلویزیون\n\n• خدمات ملحفه و حوله\n\n• نظافت حرفه‌ای\n\n🌿 فضای بیرونی\n\n• باغ اختصاصی و محصور\n\n• تراس بزرگ\n\n• محل کباب و منقل\n\n• مبلمان باغ\n\n• پارکینگ اختصاصی\n\n• موقعیت آرام در دل طبیعت\n\n📍 مزیت موقعیت\n\nویلای ما در فضای آرام و سرسبز دواجی قرار دارد و از نظر دسترسی به مرکز شهر آنتالیا، مراکز خرید و سواحل موقعیت مناسبی دارد.\n\n📋 اطلاعات اجاره\n\n🕑 ورود: 14:00\n\n🕚 خروج: 11:00\n\n• برای تمام مهمانان اقامت‌کننده، ثبت هویت در سامانه KBS انجام می‌شود.\n\n• پذیرش حیوان خانگی ممکن نیست.\n\n• برای مهمانی و مراسم مناسب نیست.\n\n• قیمت‌ها بسته به فصل، ایام تعطیلات و مدت اقامت ممکن است تغییر کند.\n\nگواهی مجوز اجاره مسکن برای مقاصد گردشگری موجود است.\n\n📞 رزرو و اطلاعات:\n\nایشاک کهرمان – کا گلوبال اینشاات املاک\n\n0532 224 76 58\n\nبرای اطلاع از قیمت روز، موجودی و رزرو می‌توانید تماس بگیرید.\n\nکا گلوبال – اجاره کوتاه‌مدت\n\n🏡 اقامت روزانه • هفتگی • ماهانه\n\n📍 آنتالیا / ترکیه\n\n🌍 ترکی • انگلیسی • فارسی\n\nما با اطمینان کا گلوبال، گزینه‌های مطمئن، راحت و ممتاز اقامت کوتاه‌مدت در آنتالیا را ارائه می‌کنیم.\n\n🏠 ویلا • آپارتمان • رزیدانس\n\n🌊 گزینه‌های نزدیک به دریا\n\n🏊 گزینه‌های استخردار و داخل مجتمع مسکونی\n\n📅 اجاره روزانه • هفتگی • ماهانه\n\n📞 برای اطلاعات بیشتر و رزرو با ما تماس بگیرید.\n\nکا گلوبال – املاک و ساخت‌وساز\n\nآنتالیا","features":["مبله","گاز طبیعی","پکیج"],"auto":true,"sourceHash":"e3ebbb1d7cd93b14"}}},{"id":"a09cd03c-29e2-437e-b393-aeed11217cc0","translations":{"en":{"title":"2+1 apartment for sale in a gated complex with a pool in Hurma","description":"ANTALYA / KONYAALTI / HURMA MAHALLESİ\n\nOur apartment for sale in a gated complex on Hurma Mahallesi 252. Sokak, in a location with convenient transport, is waiting for its new owner.\n\nAPARTMENT FEATURES\n\nOn the 2nd floor of a 4-storey building\n\nWith elevator\n\nIn a gated complex\n\nComplex pool\n\nNatural gas\n\nBus stop right in front of the building\n\nCentral location with easy transport\n\nLOCATION ADVANTAGES\n\nThanks to the bus stop right in front of the apartment, public transport is very convenient.\n\nLocated in one of the preferred areas of Hurma Mahallesi, the property can be considered for both living and investment purposes.\n\nREAL ESTATE SERVICE FEE\n\nReal estate service fee: 2% of the sale price + VAT will be collected from the buyer.\n\nFor detailed information, price and an on-site viewing:\n\nKA EMLAK\n\n📞 0532 224 76 58","features":["Natural gas","Air conditioning","Eligible for a mortgage"],"auto":true,"sourceHash":"82ed7e443a380325"},"fa":{"title":"آپارتمان 2+1 استخردار داخل مجتمع مسکونی برای فروش در هورما","description":"آنتالیا / کنیاآلتی / محله هورما\n\nآپارتمان فروشی ما داخل مجتمع مسکونی، در خیابان 252 محله هورما و در موقعیتی با دسترسی مناسب، در انتظار صاحب جدید است.\n\nویژگی‌های آپارتمان\n\nطبقه 2 ساختمان 4 طبقه\n\nآسانسوردار\n\nداخل مجتمع مسکونی\n\nدارای استخر مجتمع\n\nگاز طبیعی\n\nایستگاه اتوبوس درست جلوی ساختمان\n\nموقعیت مرکزی و با دسترسی آسان\n\nمزایای موقعیت\n\nوجود ایستگاه اتوبوس درست جلوی آپارتمان، رفت‌وآمد با وسایل حمل‌ونقل عمومی را بسیار راحت کرده است.\n\nاین ملک که در یکی از مناطق مورد توجه محله هورما قرار دارد، هم برای سکونت و هم برای سرمایه‌گذاری قابل استفاده است.\n\nکمیسیون خدمات املاک\n\nکمیسیون خدمات املاک: 2% مبلغ فروش + مالیات بر ارزش افزوده (KDV) از خریدار دریافت خواهد شد.\n\nبرای اطلاعات بیشتر، قیمت و بازدید حضوری:\n\nکا املاک\n\n📞 0532 224 76 58","features":["گاز طبیعی","کولر","قابل دریافت وام بانکی"],"auto":true,"sourceHash":"82ed7e443a380325"}}},{"id":"1fee09a5-a3e3-4180-b0d4-7ccd131fd74b","translations":{"en":{"title":"1+1 apartment for rent in Liman with natural gas and two air conditioners","description":"1+1 Apartment for Rent in Liman, Konyaaltı, Antalya, with Natural Gas & 2 Air Conditioners\n\nA comfortable, hassle-free 1+1 apartment for rent in Liman Mahallesi, a sought-after area of Konyaaltı!\n\nApartment Features:\n\nNumber of rooms: 1+1\n\nGross / Net: 60 m² / 50 m²\n\nHeating: Combi boiler (natural gas)\n\nAir conditioning: 2 air conditioners\n\nEquipment: Built-in set available\n\nBuilding: Single-block, tidy apartment building (building age: 6-10 years)\n\nLocation and Transport:\n\nLocated in the central part of Liman Mahallesi, our apartment is within walking distance of chain supermarkets, public transport stops, social amenities and the beach.\n\nRental Terms:\n\nMonthly rent: 25.000 TL\n\nPlease contact us for detailed information and an appointment.","features":["Natural gas","Combi boiler"],"auto":true,"sourceHash":"54942a015bdc7d21"},"fa":{"title":"آپارتمان 1+1 اجاره‌ای در لیمان با گاز طبیعی و دو کولر","description":"آپارتمان 1+1 اجاره‌ای با گاز طبیعی و 2 کولر در لیمان کنیاآلتی، آنتالیا\n\nآپارتمان 1+1 اجاره‌ای راحت و بدون نیاز به هزینه اضافی در محله لیمان، از محبوب‌ترین مناطق کنیاآلتی!\n\nویژگی‌های آپارتمان:\n\nتعداد اتاق: 1+1\n\nناخالص / خالص: 60 m² / 50 m²\n\nگرمایش: پکیج (گاز طبیعی)\n\nتهویه مطبوع: 2 عدد کولر\n\nتجهیزات: وسایل توکار موجود است\n\nساختمان: آپارتمان خوش‌نام تک‌بلوکی (سن بنا: 6-10 سال)\n\nموقعیت و دسترسی:\n\nآپارتمان ما در موقعیت مرکزی محله لیمان قرار دارد و تا فروشگاه‌های زنجیره‌ای، ایستگاه‌های حمل‌ونقل عمومی، امکانات اجتماعی و ساحل فاصله پیاده‌روی دارد.\n\nشرایط اجاره:\n\nاجاره ماهیانه: 25.000 TL\n\nبرای اطلاعات بیشتر و هماهنگی بازدید لطفاً تماس بگیرید.","features":["گاز طبیعی","پکیج"],"auto":true,"sourceHash":"54942a015bdc7d21"}}},{"id":"66dc8038-a373-42b4-94e2-20aee217bc11","translations":{"en":{"title":"Office for rent in Kuşkavağı with garden and two bathrooms","description":"A prestigious and comfortable opportunity for your business and working environment, in the most refined location of Konyaaltı Kuşkavağı Mahallesi!\n\nLocated on the ground floor of a stylish two-storey villa, this special property has an extremely spacious and airy layout, ideal for both a corporate office and residential / home-office use.\n\nKEY FEATURES:\n\nSpacious Usable Area: Net ~80 m² usable area\n\nRoom Layout: 2 Large Separate Rooms + Separate Kitchen (Very Spacious and Practical 1+1 Format)\n\nBathrooms: 2 Separate Bathrooms & WCs\n\nOutdoor Areas: 2 Large Balconies + Use of a Large, Pleasant Private Garden\n\nGround-Floor Advantage: Very suitable for customer and staff access, with the feel of a separate entrance\n\nWorking Environment: Quiet, prestigious and airy atmosphere in the midst of nature\n\nLOCATION & TRANSPORT:\n\nIn a developing and appreciating area of Konyaaltı; very close to main roads, public transport, corporate hubs and social amenities.","features":["50 m² outdoor area"],"auto":true,"sourceHash":"795d8c7b7a5c761a"},"fa":{"title":"دفتر کار اجاره‌ای با باغ و دو حمام در کوشکاوایی","description":"در بهترین موقعیت محله کوشکاوایی کنیاآلتی، فرصتی معتبر و راحت برای کسب‌وکار و محیط کاری شما!\n\nاین ملک ویژه در طبقه همکف یک ویلای دوطبقه شیک قرار دارد و با معماری بسیار بزرگ و جادارش، هم برای دفتر کار شرکتی و هم برای استفاده مسکونی / هوم‌آفیس ساختار عالی دارد.\n\nویژگی‌های برجسته:\n\nفضای قابل استفاده بزرگ: حدود 80 m² فضای مفید خالص\n\nچیدمان اتاق‌ها: 2 اتاق بزرگ مستقل + آشپزخانه جداگانه (در قالب 1+1 بسیار بزرگ و کاربردی)\n\nحمام: 2 عدد حمام و سرویس بهداشتی مستقل\n\nفضای باز: 2 بالکن بزرگ + استفاده از باغ اختصاصی بزرگ و دلپذیر\n\nمزیت طبقه همکف: بسیار مناسب برای دسترسی مشتری و کارکنان، با حس ورودی مستقل\n\nمحیط کار: آرام، معتبر و جادار در دل طبیعت\n\nموقعیت و دسترسی:\n\nدر منطقه رو به رشد و ارزشمندشونده کنیاآلتی؛ بسیار نزدیک به راه‌های اصلی، حمل‌ونقل عمومی، مراکز شرکتی و امکانات اجتماعی قرار دارد.","features":["50 m² فضای باز"],"auto":true,"sourceHash":"795d8c7b7a5c761a"}}},{"id":"d4319f8a-3173-4a1b-aadc-e5957dd13fdc","translations":{"en":{"title":"3+1 attic duplex apartment for sale in Hurma","description":"Attic Duplex Apartment for Sale in Hurma Mahallesi, Konyaaltı, Antalya!\n\nSince the title deed is more than five years old, the property is eligible for sale through mortgage and financing companies\n\nDuplex residence for sale in our complex located on a 1.581 m² plot in Hurma Mahallesi, one of the most preferred and rapidly appreciating areas of Konyaaltı.\n\nKey Features:\n\nLocation: Konyaaltı / Hurma Mahallesi  Floor plan: 3rd Floor + Attic Duplex\n\nOwnership status: Condominium easement (kat irtifaklı), full share on the title deed  Building/Complex area: A large complex layout with a total plot area of 1.581 m²  It is an extremely ideal location for both living and investment.\n\nPlease contact us for detailed information and an appointment.\n\nPegah ZARE\n\n0 538 214 73 35","features":["Combi boiler","Eligible for a mortgage"],"auto":true,"sourceHash":"2aabec35cae6a54c"},"fa":{"title":"آپارتمان دوبلکس زیر شیروانی 3+1 برای فروش در هورما","description":"آپارتمان دوبلکس زیر شیروانی برای فروش در محله هورما، کنیاآلتی، آنتالیا!\n\nاز آنجا که سند مالکیت بیش از پنج سال قدمت دارد، برای فروش با وام بانکی و شرکت‌های تأمین مالی مناسب است\n\nدر محله هورما، یکی از پرطرفدارترین مناطق کنیاآلتی که به سرعت ارزشمند می‌شود،\n\nواحد مسکونی دوبلکس برای فروش در مجتمع ما که در زمین 1.581 m² قرار دارد.\n\nویژگی‌های برجسته:\n\nموقعیت: کنیاآلتی / محله هورما  طرح طبقه: طبقه 3 + دوبلکس زیر شیروانی\n\nوضعیت مالکیت: مالکیت طبقاتی در مرحله ساخت (کات ایرتیفاکلی)،\n\nسند به‌صورت شش‌دانگ  مساحت ساختمان/مجتمع: مجموعه بزرگ مسکونی با زمین مجموعاً 1.581 m²  هم برای سکونت و هم برای سرمایه‌گذاری در موقعیتی بسیار ایده‌آل قرار دارد.\n\nبرای اطلاعات بیشتر و هماهنگی بازدید لطفاً تماس بگیرید.\n\nپگاه زارع\n\n0 538 214 73 35","features":["پکیج","قابل دریافت وام بانکی"],"auto":true,"sourceHash":"2aabec35cae6a54c"}}},{"id":"59153a1d-6b81-46a3-950f-1805d6292152","translations":{"en":{"title":"2+1 office for rent in a plaza on Atatürk Bulvarı","description":"IN ÖĞRETMENEVLERİ MAHALLESİ, KONYAALTI, ANTALYA\n\n2+1 LUXURY OFFICE FOR RENT IN A PREMIUM PLAZA ON ATATÜRK BULVARI\n\nOn Atatürk Bulvarı, one of the most prestigious locations in Konyaaltı, in the Premium Plaza very close to the sea, a 2+1 office for rent suited to corporate firms is waiting for you. The area is an important location for businesses that want to increase brand awareness, with high signage value and heavy vehicle and pedestrian traffic. (hepsiemlak)\n\nOffice Features\n• 📍 Öğretmenevleri Mahallesi – On Atatürk Bulvarı\n• 🏢 Premium Plaza – 1st floor of a 5-storey building\n• 📐 110 m² spacious usable area\n• 🛋️ 2+1 office layout\n• 🍽️ Separate kitchen\n• 🌞 Two bright, airy rooms with fully glazed front facade\n• 🚗 Indoor parking\n• 🌊 Walking distance to the sea\n• 💼 Prestigious, corporate working environment\n\nWho Is It Suitable For?\n• Health centres\n• Doctors' and dentists' practices\n• Law offices\n• Financial advisory and accounting offices\n• Architecture and engineering firms\n• Consultancy companies\n• All businesses looking for a corporate office\n\nAn exceptional office opportunity that will strengthen your company's corporate image with its premium location on Atatürk Bulvarı, high signage visibility and prestigious plaza building.\n\n💰 Monthly rent: 60.000 TL\n\nPlease contact us for detailed information and an on-site viewing.","features":[],"auto":true,"sourceHash":"b3a4564fe52960e5"},"fa":{"title":"دفتر کار 2+1 اجاره‌ای داخل پلازا در بلوار آتاتورک","description":"در محله اؤیرتمن‌اولری کنیاآلتی\n\nدفتر کار لوکس 2+1 اجاره‌ای در پلازای پریمیوم، در بلوار آتاتورک\n\nدفتر کار 2+1 اجاره‌ای در پریمیوم پلازا، در یکی از معتبرترین موقعیت‌های کنیاآلتی یعنی بلوار آتاتورک و بسیار نزدیک به دریا، منتظر شماست؛ مناسب شرکت‌های سازمانی. این منطقه با ارزش تابلوی بالا و ترافیک زیاد خودرو و عابر پیاده، برای کسب‌وکارهایی که می‌خواهند شناخته‌شدن برندشان را افزایش دهند موقعیت مهمی است. (هپسی‌املاک)\n\nویژگی‌های دفتر کار\n• 📍 محله اؤیرتمن‌اولری – در بلوار آتاتورک\n• 🏢 پریمیوم پلازا – طبقه 1 ساختمان 5 طبقه\n• 📐 110 m² فضای قابل استفاده بزرگ\n• 🛋️ طرح دفتر 2+1\n• 🍽️ آشپزخانه جداگانه\n• 🌞 2 اتاق جادار و روشن با نمای جلوی کاملاً شیشه‌ای\n• 🚗 پارکینگ سرپوشیده\n• 🌊 فاصله پیاده‌روی تا دریا\n• 💼 محیط کاری معتبر و سازمانی\n\nمناسب چه کسانی است؟\n• مراکز درمانی\n• مطب پزشکان و دندانپزشکان\n• دفاتر وکالت\n• دفاتر مشاوره مالی و حسابداری\n• شرکت‌های معماری و مهندسی\n• شرکت‌های مشاوره\n• تمام کسب‌وکارهایی که به دنبال دفتر کار سازمانی هستند\n\nدفتر کاری ممتاز که با موقعیت پریمیوم در بلوار آتاتورک، دید بالای تابلو و ساختمان معتبر پلازا، تصویر سازمانی شرکت شما را تقویت می‌کند.\n\n💰 اجاره ماهیانه: 60.000 TL\n\nبرای اطلاعات بیشتر و بازدید حضوری با ما تماس بگیرید.","features":[],"auto":true,"sourceHash":"b3a4564fe52960e5"}}},{"id":"2e10ff21-b40b-4141-bb72-e89c8d0eefeb","translations":{"en":{"title":"Entire building for sale in Yeniköy, Döşemealtı","description":"BRAND-NEW ENTIRE BUILDING FOR SALE IN YENİKÖY, DÖŞEMEALTI\n\nA brand-new entire building with occupancy permit, built on a 432 m² plot in Yeniköy Mahallesi, Döşemealtı, Antalya, and completed with quality workmanship and first-class materials, is offered for sale.\n\nBuilding Features\n\nBuilt on a 432 m² plot\n\nA total of 4 ready 2+1 apartments\n\nEach apartment has approximately 125 m² of gross usable area.\n\nSpacious, airy living areas\n\nOccupancy permit obtained\n\nImmediate delivery\n\nApartment Features\n\n2+1 spacious and practical layout\n\nUnderfloor heating system\n\nComplete lacquered kitchen and interior doors\n\nFirst-class workmanship and quality materials\n\nModern architecture\n\nBright and airy living areas\n\nInvestment Advantage\n\nThere is potential to build a 5th apartment on the attic floor. (This may be assessed within the scope of the relevant regulations and technical suitability.)\n\nIt has high potential in terms of both investment and rental income.\n\n📞 We are the sole authorised real estate office for this portfolio.\n🤝 Open to sharing with fellow agents.\nYou can contact us for detailed information, an on-site presentation and an appointment.","features":["Air conditioning","Tenanted"],"auto":true,"sourceHash":"27bbc195ba763f7d"},"fa":{"title":"ساختمان کامل برای فروش در یئنی‌کوی دوشمه‌آلتی","description":"ساختمان کامل نوساز برای فروش در یئنی‌کوی دوشمه‌آلتی\n\nدر محله یئنی‌کوی دوشمه‌آلتی آنتالیا، یک ساختمان کامل نوساز و دارای پایان‌کار که با کیفیت اجرای بالا و مصالح درجه یک روی زمین 432 m² ساخته و تکمیل شده، برای فروش عرضه شده است.\n\nویژگی‌های ساختمان\n\nساخته‌شده روی زمین 432 m²\n\nدر مجموع 4 واحد آماده 2+1\n\nهر واحد حدود 125 m² فضای ناخالص دارد.\n\nفضاهای زندگی بزرگ و جادار\n\nپایان‌کار گرفته شده است.\n\nتحویل فوری\n\nویژگی‌های واحدها\n\nپلان 2+1 بزرگ و کاربردی\n\nسیستم گرمایش از کف\n\nآشپزخانه کامل لاکی و درهای داخلی\n\nاجرای درجه یک و مصالح با کیفیت\n\nمعماری مدرن\n\nفضاهای زندگی روشن و جادار\n\nمزیت سرمایه‌گذاری\n\nامکان ساخت واحد پنجم در طبقه زیر شیروانی وجود دارد. (بسته به مقررات مربوطه و تناسب فنی قابل بررسی است.)\n\nهم از نظر سرمایه‌گذاری و هم از نظر درآمد اجاره، پتانسیل بالایی دارد.\n\n📞 ما تنها دفتر املاک مجاز این ملک هستیم.\n🤝 برای همکاری با همکاران املاکی آماده است.\nبرای اطلاعات بیشتر، ارائه حضوری و هماهنگی بازدید با ما تماس بگیرید.","features":["کولر","دارای مستأجر"],"auto":true,"sourceHash":"27bbc195ba763f7d"}}},{"id":"9c55fa35-945a-4a61-8cec-716af713b932","translations":{"en":{"title":"250 m² 4+1 duplex in a new building in Fevzi Çakmak","description":"A 4+1 duplex apartment, notable for its modern architecture and spacious usable area, is offered for sale in Fevzi Çakmak Mahallesi, Kepez, Antalya.\n\nKey Features:\n\n4+1 duplex\n\n250 m² gross / 240 m² net\n\nBrand-new building\n\nIn a 4-storey, 2-block complex\n\nOn the 4th floor of the building\n\n2 bathrooms\n\nCondominium ownership title deed (kat mülkiyetli)\n\nAiry and practical interior\n\nModern fixed-furniture living room wall unit\n\nAir conditioning for heating/cooling\n\nSale price: 6.400.000 TL\n\nAn option worth considering for those looking for a spacious, new duplex home.\n\nPlease contact us for detailed information and an on-site viewing.\n\nKA EMLAK","features":["Air conditioning"],"auto":true,"sourceHash":"61c0b27ea250b231"},"fa":{"title":"دوبلکس 4+1 به متراژ 250 m² در ساختمان نوساز در فوزی چاکماک","description":"در محله فوزی چاکماک کپز آنتالیا، یک آپارتمان دوبلکس 4+1 که با معماری مدرن و فضای بزرگش جلب توجه می‌کند، برای فروش عرضه شده است.\n\nویژگی‌های برجسته:\n\nدوبلکس 4+1\n\n250 m² ناخالص / 240 m² خالص\n\nساختمان نوساز\n\nداخل مجتمع مسکونی 4 طبقه با 2 بلوک\n\nدر طبقه 4 ساختمان\n\n2 حمام\n\nسند مالکیت طبقاتی\n\nفضای داخلی جادار و کاربردی\n\nیونیت دیواری سالن مدرن و ثابت (مبلمان توکار)\n\nگرمایش/سرمایش با کولر\n\nقیمت فروش: 6.400.000 TL\n\nگزینه‌ای قابل بررسی برای کسانی که به دنبال زندگی در فضای بزرگ، نوساز و دوبلکس هستند.\n\nبرای اطلاعات بیشتر و بازدید حضوری می‌توانید تماس بگیرید.\n\nکا املاک","features":["کولر"],"auto":true,"sourceHash":"61c0b27ea250b231"}}},{"id":"e0820545-9244-4843-a76d-a7b5ad5e1d1a","translations":{"en":{"title":"Daily rental villa with private pool in Hisarçandır","description":"You are invited to an unforgettable holiday experience in the lap of nature, in a captivating atmosphere.\n\nVilla Badem, notable for its modern design,\n\ncombines the warmth of stone and wood with luxurious details.\n\nWake up to birdsong,\n\nfacing a magnificent mountain view.\n\nAs you cool off in your spacious private pool,\n\nfeel the peace nature offers with your whole being.\n\nWith its fully equipped kitchen,\n\ncomfortable living areas and architecture thought out down to every detail, this is not just a place to stay, but a retreat where you can rest your soul.\n\nBook your place now to surrender yourself to the enchanting embrace of nature and to experience the privilege of Silyan Villas.\"\n\nPRICES=\n\nDaily 300-450-550 EURO\n\nMONTHLY 3500-4500-5500 EURO\n\n3 different villa options are available.","features":["Air conditioning"],"auto":true,"sourceHash":"6d9e2c0781cd4899"},"fa":{"title":"ویلای اجاره روزانه با استخر اختصاصی در هیسارچاندیر","description":"شما به یک تجربه تعطیلات فراموش‌نشدنی در آغوش طبیعت و در فضایی افسونگر دعوت شده‌اید.\n\nویلا بادم که با طراحی مدرنش جلب توجه می‌کند،\n\nگرمای سنگ و چوب را با جزئیات لوکس ترکیب می‌کند.\n\nبا صدای پرندگان از خواب بیدار شوید،\n\nرو به منظره عظیم کوهستان.\n\nوقتی در استخر بزرگ اختصاصی‌تان خنک می‌شوید،\n\nآرامشی را که طبیعت به شما می‌بخشد با تمام وجود حس کنید.\n\nبا آشپزخانه کاملاً مجهز،\n\nفضاهای زندگی راحت و معماری که تمام جزئیاتش با دقت فکر شده، اینجا فقط یک محل اقامت نیست؛ پناهگاهی است که روح شما را آرام می‌کند.\n\nبرای رها کردن خود در آغوش افسونگر طبیعت و تجربه امتیازهای سیلیان ویلاز، همین حالا جای خود را رزرو کنید.\"\n\nقیمت‌ها=\n\nروزانه 300-450-550 یورو\n\nماهانه 3500-4500-5500 یورو\n\n3 گزینه ویلای متفاوت موجود است.","features":["کولر"],"auto":true,"sourceHash":"6d9e2c0781cd4899"}}},{"id":"3f5ebc86-4297-4e40-8285-418a00fc0f73","translations":{"en":{"title":"Custom light steel villa construction on your plot","description":"LIGHT STEEL VILLA | 12.000 TL/m² VAT INCLUDED | ANTALYA | ARCHITECTURAL DESIGN TAILORED TO YOUR PLOT\n\nWe offer special solutions for customers in Antalya and the surrounding area who want to have a modern, safe and economical light steel villa built on their plot.\n\nOur light steel construction system offers a strong alternative to reinforced concrete buildings with its fast production, short assembly time, high durability, architectural flexibility and economic cost advantage. You can choose from our ready-made plans, or you can get architectural design service tailored to your plot and needs.\n\nOUR STANDARD LIGHT STEEL VILLA PRICE\n\n12.000 TL/m² VAT INCLUDED\n\nOur price is valid for the standard system.\n\nOur exterior wall and interior wall systems are applied as standard at 10 cm thickness.\n\nNOTE:\n\nPlinth waterproofing (su basmanı), foundation concrete, ground preparation, building permit fees, official permit costs and extra works depending on the land are not included in our price. The price may vary depending on the land conditions, project size, plan type and material preferences.\n\nSCOPE OF OUR SERVICE\n• Architectural planning suited to your plot\n• 2D architectural plan work\n• Light steel load-bearing system installation\n• Wall and roof cladding\n• Thermal and sound insulation\n• Interior and exterior facade cladding\n• Electrical installation infrastructure\n• Plumbing installation infrastructure\n• Roof and rain gutter works\n• Window and door installation\n• Optional interior layout and material selection\n• Optional landscaping, veranda, pool and outdoor concept design\n\nWORKS THAT CAN BE INCLUDED IN THE STANDARD PACKAGE\n• Light steel frame system\n• Exterior facade cladding\n• Interior wall cladding\n• Roof system\n• Roof insulation\n• Rain gutters and downpipes\n• PVC window systems\n• Interior and exterior door installation\n• Electrical installation\n• Clean water and waste water installation\n• Ceramic work in wet areas\n• Interior and exterior paint work\n• Laminate flooring\n• Kitchen cabinets and countertop\n• Bathroom sanitary ware\n• Shower cabin, toilet and washbasin installation\n\nMaterial colours, ceramics, flooring, paint, kitchen cabinets and door options can be determined according to the customer's preference during the project stage.\n\nWHY A LIGHT STEEL VILLA?\n\nFast Production and Assembly\n\nLight steel systems can be produced in a much shorter time than traditional buildings and assembled quickly on site.\n\nEarthquake*  Safe System\n\nThanks to its lightness and flexible structure, the steel load-bearing system offers a safe building solution. The design process is carried out in accordance with the regulations in force.\n\nEconomical and Long-Lasting Solution\n\nIt is a building system with low maintenance costs, a long service life and high investment value.\n\nArchitectural Flexibility\n\n2+1, 3+1, 4+1 villas, vineyard houses, highland houses, farmhouses, tiny-house-style buildings and custom plan solutions can be produced.\n\nInsulated and Comfortable Living Space\n\nWith the right insulation details, comfortable living spaces that are cool in summer and warm in winter are created.\n\nWHO IS IT SUITABLE FOR?\n• Those who want to build a villa on their plot\n• Those considering a vineyard house / detached house in Antalya and the surrounding area\n• Those looking for an economical and fast building solution\n• Those who want an earthquake*  safe light steel system\n• Those who want their own custom architectural design instead of a ready-made project\n• Those who want to build an investment property or a summer house\n\nDELIVERY AND PRICING NOTE\n\nThe stated price of 12.000 TL/m² VAT included is the starting price for the standard light steel building system.\n\nThe price may change according to the project's area in square metres, number of rooms, roof type, facade material, interior quality, land conditions and scope of delivery.\n\nPlinth waterproofing and foundation works are priced separately according to the land structure.\n\nDETAILED INFORMATION AND APPOINTMENT\n\nYou can contact us for your projects in Antalya and the surrounding area.\n\nCall now for planning tailored to your plot, architectural design, technical specification and a price quote.\n\nWe offer professional solutions for light steel villas, prefabricated houses, steel houses, vineyard houses, highland houses and modern living spaces tailored to your plot.\n• \"hepsiemlak cannot give any commitment regarding the earthquake resistance of this property. Please speak with the listing owner for detailed information.\"","features":[],"auto":true,"sourceHash":"66d70dbe81f3632a"},"fa":{"title":"ساخت ویلای سازه سبک فولادی مخصوص زمین شما","description":"ویلای سازه سبک فولادی | 12.000 TL/m² با KDV | آنتالیا | طراحی معماری مخصوص زمین شما\n\nبه مشتریانی که می‌خواهند در آنتالیا و اطراف آن روی زمین خود یک ویلای سازه سبک فولادی مدرن، ایمن و اقتصادی بسازند، راه‌حل‌های ویژه ارائه می‌دهیم.\n\nسیستم ساختمانی سازه سبک فولادی ما با مزایای تولید سریع، زمان نصب کوتاه، مقاومت بالا، انعطاف معماری و هزینه اقتصادی، جایگزین قدرتمندی برای سازه‌های بتنی است. هم می‌توانید از پلان‌های آماده ما انتخاب کنید و هم از خدمات طراحی معماری مخصوص زمین و نیازهای خود بهره‌مند شوید.\n\nقیمت استاندارد ویلای سازه سبک فولادی ما\n\n12.000 TL/m² با KDV\n\nقیمت ما برای سیستم استاندارد معتبر است.\n\nدیوار خارجی و دیوار داخلی ما به‌طور استاندارد با ضخامت 10 cm اجرا می‌شود.\n\nتوجه:\n\nپی‌کار آب‌بند (سوکل)، بتن پی، آماده‌سازی زمین، عوارض پروانه، هزینه‌های مجوزهای رسمی و کارهای اضافی وابسته به زمین در قیمت ما شامل نیست. قیمت بسته به وضعیت زمین، اندازه پروژه، نوع پلان و انتخاب مصالح ممکن است تغییر کند.\n\nمحدوده خدمات ما\n• طراحی معماری متناسب با زمین شما\n• تهیه پلان معماری دوبعدی\n• نصب سیستم باربر سازه سبک فولادی\n• اجرای پوشش دیوار و سقف\n• اجرای عایق حرارتی و صوتی\n• کارهای پوشش نمای داخلی و خارجی\n• زیرساخت تأسیسات برق\n• زیرساخت تأسیسات بهداشتی\n• اجرای سقف و ناودان\n• اجرای پنجره و در\n• طراحی داخلی و انتخاب مصالح (اختیاری)\n• طراحی فضای سبز، تراس، استخر و فضای بیرونی (اختیاری)\n\nکارهایی که در بسته استاندارد قابل اجرا است\n• اسکلت سازه سبک فولادی\n• پوشش نمای خارجی\n• پوشش نمای داخلی\n• سیستم سقف\n• عایق سقف\n• ناودان و لوله‌های آن\n• سیستم‌های پنجره PVC\n• اجرای درهای داخلی و خارجی\n• تأسیسات برق\n• لوله‌کشی آب تمیز و فاضلاب\n• اجرای سرامیک فضاهای مرطوب\n• اجرای رنگ نمای داخلی و خارجی\n• اجرای پارکت لمینت\n• اجرای کابینت و کانتر آشپزخانه\n• لوازم بهداشتی حمام\n• اجرای کابین دوش، توالت فرنگی و دستشویی\n\nرنگ مصالح و گزینه‌های سرامیک، پارکت، رنگ، کابینت آشپزخانه و در می‌تواند در مرحله پروژه بر اساس ترجیح مشتری تعیین شود.\n\nچرا ویلای سازه سبک فولادی؟\n\nتولید و نصب سریع\n\nسیستم‌های سبک فولادی را می‌توان در زمان بسیار کوتاه‌تری نسبت به سازه‌های سنتی تولید کرد و در محل سریع نصب کرد.\n\nسیستم ایمن در برابر زلزله*\n\nسیستم باربر فولادی به لطف سبکی و ساختار انعطاف‌پذیرش راه‌حل ساختمانی ایمنی ارائه می‌دهد. فرایند طراحی پروژه مطابق مقررات جاری تهیه می‌شود.\n\nراه‌حل اقتصادی و بادوام\n\nسیستمی ساختمانی با هزینه نگهداری کم، عمر استفاده طولانی و ارزش سرمایه‌گذاری بالا.\n\nانعطاف معماری\n\nویلاهای 2+1، 3+1، 4+1، خانه باغی، خانه ییلاقی، خانه مزرعه‌ای، ساختمان‌هایی به سبک تاینی هاوس و راه‌حل‌های پلان اختصاصی قابل تولید است.\n\nفضای زندگی عایق‌شده و راحت\n\nبا جزئیات عایق‌کاری درست، فضاهای زندگی راحت ایجاد می‌شود که تابستان خنک و زمستان گرم است.\n\nبرای چه کسانی مناسب است؟\n• کسانی که می‌خواهند روی زمین خود ویلا بسازند\n• کسانی که در آنتالیا و اطراف آن به خانه باغی / خانه مستقل فکر می‌کنند\n• کسانی که به دنبال راه‌حل ساختمانی اقتصادی و سریع هستند\n• کسانی که سیستم سازه سبک فولادی ایمن در برابر زلزله* می‌خواهند\n• کسانی که به جای پروژه آماده، طراحی معماری اختصاصی می‌خواهند\n• کسانی که می‌خواهند بنای سرمایه‌گذاری یا ییلاقی بسازند\n\nنکته تحویل و قیمت‌گذاری\n\nقیمت ذکرشده 12.000 TL/m² با KDV، قیمت شروع برای سیستم ساختمانی استاندارد سازه سبک فولادی است.\n\nقیمت بسته به متراژ پروژه، تعداد اتاق، نوع سقف، مصالح نما، کیفیت فضای داخلی، شرایط زمین و دامنه تحویل ممکن است تغییر کند.\n\nپی‌کار آب‌بند و کارهای پی بسته به ساختار زمین جداگانه قیمت‌گذاری می‌شود.\n\nاطلاعات تفصیلی و هماهنگی ملاقات\n\nبرای پروژه‌های خود در آنتالیا و اطراف آن می‌توانید با ما تماس بگیرید.\n\nبرای برنامه‌ریزی، طراحی معماری، مشخصات فنی و پیشنهاد قیمت مخصوص زمین خود همین حالا تماس بگیرید.\n\nما برای ویلای سازه سبک فولادی، خانه پیش‌ساخته، خانه فولادی، خانه باغی، خانه ییلاقی و فضاهای زندگی مدرن مخصوص زمین شما راه‌حل‌های حرفه‌ای ارائه می‌کنیم.\n• «هپسی‌املاک در مورد مقاوم بودن این ملک در برابر زلزله هیچ تعهدی نمی‌تواند بدهد. برای اطلاعات بیشتر لطفاً با صاحب آگهی صحبت کنید.»","features":[],"auto":true,"sourceHash":"66d70dbe81f3632a"}}},{"id":"61cdd85c-d27f-41ee-acb9-8390fea74aee","translations":{"en":{"title":"Looking for land for a land-for-flats deal or purchase in Döşemealtı","description":"Announcement to Landowners!\n\nLet Your Valuable Land Gain Value!\nWe are looking for plots in Antalya's sought-after areas Döşemealtı, Konyaaltı, Muratpaşa and Kepez on which 6-10 apartments can be built under a land-for-flats deal!\n\nWould you like to make use of your land with confidence and turn it into a profitable investment with a transparent contract and a guarantee of on-time delivery?\n\nAs KA Global İnşaat Gayrimenkul, we are ready to offer you the best terms.\n\nLet's build the project of your dreams together!\n\nCall Now: 0 532 224 76 58","features":[],"auto":true,"sourceHash":"3f48dfd0429ae6f6"},"fa":{"title":"به دنبال زمین برای مشارکت در ساخت یا خرید در دوشمه‌آلتی هستیم","description":"اطلاعیه برای صاحبان زمین!\n\nارزش زمین ارزشمند شما بالاتر برود!\nدر مناطق محبوب آنتالیا یعنی دوشمه‌آلتی، کنیاآلتی، مورات‌پاشا و کپز، به دنبال زمین‌هایی هستیم که بتوان در آن‌ها با مشارکت در ساخت، 6-10 واحد آپارتمان ساخت!\n\nآیا می‌خواهید زمین خود را با اطمینان ارزشمند کنید و با قرارداد شفاف و ضمانت تحویل به‌موقع، به یک سرمایه‌گذاری پرسود تبدیل کنید؟\n\nما به‌عنوان کا گلوبال اینشاات گایریمنکول آماده‌ایم بهترین شرایط را به شما ارائه دهیم.\n\nبیایید پروژه رویاهایتان را با هم بسازیم!\n\nهمین حالا تماس بگیرید: 0 532 224 76 58","features":[],"auto":true,"sourceHash":"3f48dfd0429ae6f6"}}},{"id":"0e04f297-6193-4c54-8fd0-fbab19991db5","translations":{"en":{"title":"Looking for 400–2.000 m² land across Antalya","description":"We Are Looking for Valuable Land Across Antalya!\n\nIn order to develop new projects in Antalya's developing areas,\n\nwe offer cash purchase or land-for-flats proposals for plots that meet the criteria below.\n\nAreas We Are Looking In:\n\nKonyaaltı & Muratpaşa: Centrally located parcels suitable for boutique or luxury housing construction.\n\nKepez & Aksu: Rapidly appreciating, zoned land that can be developed into projects.\n\nDöşemealtı: Residential plots suitable for villa construction or large-scale housing.\n\nFeatures Wanted:\n\nArea: Between 400 m2 and 2000 m2\n(Larger parcels may be considered).\n\nStatus: Individual title deed, no zoning problems, ready for construction.\n\nMethod: Cash payment or a high-ratio land-for-flats (kat karşılığı) contract, as you prefer.","features":[],"auto":true,"sourceHash":"1b6abfd705843838"},"fa":{"title":"به دنبال زمین 400 تا 2.000 m² در سراسر آنتالیا هستیم","description":"به دنبال زمین ارزشمند در سراسر آنتالیا هستیم!\n\nبرای تولید پروژه‌های جدید در مناطق در حال توسعه آنتالیا،\n\nبرای زمین‌های شما که با معیارهای زیر مطابقت دارند، پیشنهاد خرید نقدی یا مشارکت در ساخت ارائه می‌دهیم.\n\nمناطقی که به دنبال آن‌ها هستیم:\n\nکنیاآلتی و مورات‌پاشا: قطعات با موقعیت مرکزی که برای ساخت مسکونی بوتیک یا لوکس مناسب باشند.\n\nکپز و آکسو: زمین‌های دارای مجوز ساخت که به سرعت ارزشمند می‌شوند و قابل پروژه‌ریزی هستند.\n\nدوشمه‌آلتی: زمین‌های مسکونی مناسب ساخت ویلا یا در مقیاس بزرگ.\n\nویژگی‌های مورد نظر:\n\nمتراژ: بین 400 m2 تا 2000 m2\n(قطعات بزرگ‌تر قابل بررسی است).\n\nوضعیت: دارای سند مستقل، بدون مشکل کاربری و آماده ساخت.\n\nروش: به انتخاب شما پرداخت نقدی یا قرارداد مشارکت در ساخت با سهم بالا.","features":[],"auto":true,"sourceHash":"1b6abfd705843838"}}},{"id":"780d5482-a7c3-4777-ac62-74dc94044241","translations":{"en":{"title":"Looking for investment land in Muratpaşa and Konyaaltı","description":"In Muratpaşa and Konyaaltı, the heart of Antalya,\nwe are looking for plots between 400 and 2000 m2 that will add value to our projects.\n\n• Options:\n\nWhether a cash purchase or a land-for-flats proposal with a high share ratio, let's make use of your land.\n\n• Criteria:\n\nCentrally located parcels with residential or commercial zoning status are our priority.\n\n\"Our appraisal service is free of charge\" or \"Reliable, transparent process\"","features":[],"auto":true,"sourceHash":"b915172c672caab5"},"fa":{"title":"به دنبال زمین سرمایه‌گذاری در مورات‌پاشا و کنیاآلتی هستیم","description":"در قلب آنتالیا، یعنی مناطق مورات‌پاشا و کنیاآلتی،\nبه دنبال زمین‌هایی بین 400 تا 2000 m2 هستیم که به پروژه‌های ما ارزش بیفزاید.\n\n• گزینه‌ها:\n\nچه خرید نقدی و چه پیشنهادهای مشارکت در ساخت با سهم بالا، زمین شما را با هم ارزشمند کنیم.\n\n• معیارها:\n\nقطعات با موقعیت مرکزی که کاربری آن‌ها مسکونی یا تجاری است در اولویت ماست.\n\n\"خدمات کارشناسی ما رایگان است\" یا \"فرایند مطمئن و شفاف\"","features":[],"auto":true,"sourceHash":"b915172c672caab5"}}},{"id":"30272cac-0db2-44c4-9ac3-5deab2a5d03e","translations":{"en":{"title":"Shop for sale in Varsak Karşıyaka, 3 floors with a wide frontage","description":"3-STOREY COMMERCIAL PREMISES FOR SALE IN VARSAK KARŞIYAKA MAHALLESİ, KEPEZ\n\n📍 Location: Antalya / Kepez / Varsak Karşıyaka Mahallesi\n\n💰 Sale price: 7.250.000 TL\n\nOur 3-storey property, located in the developing Varsak Karşıyaka area whose commercial potential grows every day, with high signage value and a large vehicle/loading area, is for sale.\n\n📐 Technical Features & Details\n\nTotal usable area: 115 m²\n\nFloor plan: 3 floors (Ground Floor + Basement Floor + Upper Floor)\n\nInfrastructure: WC, bathroom and washbasin available\n\nFrontage & access: Wide frontage suitable for vehicle entry, with a private-use area in front suitable for loading and unloading\n\nIntended use: Floor layout fully suited to storage, manufacturing, technical service and office use\n\n✅ Suitable Sectors & Lines of Business\n\nAuto service, detailed vehicle cleaning, auto electrical and mechanical maintenance\n\nE-commerce storage, cargo and logistics centres\n\nWorkshops, furniture, aluminium & PVC joinery workshops\n\nSignage/advertising production and technical service stations\n\nWholesale and showroom stores\n\n📲 You can contact us for detailed information and viewing:\n\nKA Global Real Estate\n\nİshak KAHRAMAN\n\n📞 Phone: 0 532 224 76 58","features":["Eligible for a mortgage"],"auto":true,"sourceHash":"7c01db4a56fc4f42"},"fa":{"title":"مغازه 3 طبقه با نمای عریض برای فروش در وارساک کارشیاکا","description":"مغازه و محل کار تجاری 3 طبقه برای فروش در محله وارساک کارشیاکا کپز\n\n📍 موقعیت: آنتالیا / کپز / محله وارساک کارشیاکا\n\n💰 قیمت فروش: 7.250.000 TL\n\nملک 3 طبقه ما که در منطقه وارساک کارشیاکا قرار دارد؛ منطقه‌ای در حال توسعه که پتانسیل تجاری‌اش روزبه‌روز بیشتر می‌شود، با ارزش تابلوی بالا و فضای وسیع برای خودرو/بارگیری، برای فروش است.\n\n📐 مشخصات فنی و جزئیات\n\nکل فضای قابل استفاده: 115 m²\n\nطرح طبقات: 3 طبقه (طبقه ورودی + طبقه زیرزمین + طبقه بالا)\n\nزیرساخت: سرویس بهداشتی، حمام و دستشویی موجود\n\nنما و دسترسی: نمای عریض مناسب ورود خودرو، با فضای اختصاصی جلوی ملک مناسب بارگیری و تخلیه\n\nکاربری: چیدمان طبقات کاملاً متناسب با انبارداری، تولید، خدمات فنی و استفاده اداری\n\n✅ بخش‌ها و کسب‌وکارهای مناسب\n\nتعمیرگاه خودرو، نظافت دقیق خودرو، برق خودرو و تعمیرات مکانیکی\n\nانبارداری تجارت الکترونیک، مراکز پست و لجستیک\n\nکارگاه‌های تولیدی، مبلمان، درب و پنجره آلومینیوم و PVC\n\nتولید تابلو/تبلیغات و ایستگاه‌های خدمات فنی\n\nفروش عمده و فروشگاه‌های نمایشی\n\n📲 برای اطلاعات بیشتر و بازدید حضوری می‌توانید تماس بگیرید:\n\nکا گلوبال ریل استیت\n\nایشاک کهرمان\n\n📞 تلفن: 0 532 224 76 58","features":["قابل دریافت وام بانکی"],"auto":true,"sourceHash":"7c01db4a56fc4f42"}}},{"id":"2a78255d-29a9-457f-9145-7c63da1c10ba","translations":{"en":{"title":"Block-order plot in Kepez ready for urban renewal","description":"An urban renewal project on Kepez's development and renewal axis, with advantageous building height and floor-area ratio, suitable for quick site set-up and for sale. Floor-share ratios will be negotiated in person.","features":[],"auto":true,"sourceHash":"591a86712938289b"},"fa":{"title":"زمین بلوک‌نظام آماده تبدیل شهری در کپز","description":"پروژه تبدیل شهری در محور توسعه و تحول کپز، با مزیت ارتفاع طبقات و ضریب ساخت، مناسب برای راه‌اندازی سریع کارگاه و فروش. نسبت‌های تقسیم طبقات حضوری مذاکره خواهد شد.","features":[],"auto":true,"sourceHash":"591a86712938289b"}}},{"id":"fb578881-cfcc-450a-85fd-a1e74fd623c0","translations":{"en":{"title":"Urban renewal and land-for-flats for entire buildings in Konyaaltı","description":"In Konyaaltı, the location with Antalya's most valuable and prestigious coastline (in Altınkum, Gürsu, Arapsuyu, Kuşkavağı, Toros and the surrounding neighbourhoods), we offer urban renewal and land-for-flats project development services that will add value to your properties.\n\nWith our years of experience in the construction and real estate sector, we analyse the current condition of your buildings in Konyaaltı and prepare the fairest, technically and legally safest land-for-flats contract models for the rights holders.","features":[],"auto":true,"sourceHash":"6cd7c3e48b7e908e"},"fa":{"title":"ساختمان کامل در کنیاآلتی برای تبدیل شهری و مشارکت در ساخت","description":"در کنیاآلتی، با ارزشمندترین و معتبرترین ساحل آنتالیا (آلتین‌کوم، گورسو، آراپسویو، کوشکاوایی، تورس و محله‌های اطراف)، برای ارزشمندتر کردن ملک‌های شما خدمات توسعه پروژه تبدیل شهری و مشارکت در ساخت ارائه می‌دهیم.\n\nبا تجربه سال‌ها در صنعت ساخت‌وساز و املاک، وضعیت فعلی ساختمان‌های شما در کنیاآلتی را تحلیل می‌کنیم و برای صاحبان حق، عادلانه‌ترین و از نظر فنی و حقوقی مطمئن‌ترین مدل‌های قرارداد مشارکت در ساخت را تهیه می‌کنیم.","features":[],"auto":true,"sourceHash":"6cd7c3e48b7e908e"}}},{"id":"34f913f3-fa37-4479-9756-0ece218b41d0","translations":{"en":{"title":"7-storey zoned 800 m² land-for-flats plot in Konyaaltı","description":"Strategic Investment and Project Opportunities in Konyaaltı!\n\nIn Konyaaltı, an area of Antalya whose value multiplies with each passing day, we offer opportunities not to be missed for both contractor firms and landowners. With our wide portfolio and more than 20 years of construction/real estate experience in the area, we bring the right project together with the right investor.\n\nFor Contractor Firms: Land-for-Flats Plot Opportunities\n• Our Sample Portfolio: We have 800 m² plots in Konyaaltı with a high floor-area ratio and a 7-storey zoning right, offering ideal ground for land-for-flats projects.\n• Advantage:\n\nThanks to the area's developing infrastructure, high quality of life and constantly increasing housing demand, you can maximise your project's potential and develop modern housing projects that bring high premiums.\n\nFor Landowners: Land-for-Flats Assessment\n\nDo you have land but don't know how to find the right, most reliable contractor?\n• We bring your land together with the strongest and most prestigious construction firms in the area, through contracts based on mutual benefit and with a solid legal foundation.\n• You can contact us for the right share ratios and project models that will maximise the value of your land.\n\nUrban Renewal Projects and Solution Partnership\n\nWe manage Urban Renewal processes from start to finish for your old, risky buildings and complexes in Konyaaltı and the surrounding area, or those that have reached the end of their economic life.\n• We build the bridge between rights holders and contractor firms and ensure fair and profitable contracts are prepared.\n• We offer professional consultancy to multiply the value of your existing property with modern, earthquake*  resistant and luxury concepts.\n\nInfrastructure and Location Advantages\n\nThe places in our portfolio have all infrastructure facilities such as road, water, electricity and sewerage, have a clear zoning status and are in terms of location among the most dynamic points of Antalya.\n\nWhy Should You Work With Us?\n\n> We are not just a real estate office; with our expert team who know the area well and come from within the construction industry, we run a corporate process that protects the rights of both contractors and property owners.\n\n For detailed information, a portfolio presentation and cooperation opportunities, send a message or call now\n• \"hepsiemlak cannot give any commitment regarding the earthquake resistance of this property. Please speak with the listing owner for detailed information.\"","features":[],"auto":true,"sourceHash":"c5617e5dcf649465"},"fa":{"title":"زمین مشارکت در ساخت با مجوز 7 طبقه و 800 m² در کنیاآلتی","description":"فرصت‌های راهبردی سرمایه‌گذاری و پروژه در کنیاآلتی!\n\nدر کنیاآلتی، منطقه‌ای از آنتالیا که ارزشش روزبه‌روز چند برابر می‌شود، هم برای شرکت‌های پیمانکار و هم برای صاحبان زمین فرصت‌هایی ارائه می‌دهیم که نباید از دست بروند. با پرتفوی گسترده و بیش از 20 سال تجربه ساخت‌وساز/املاک در منطقه، پروژه درست را با سرمایه‌گذار درست آشنا می‌کنیم.\n\nبرای شرکت‌های پیمانکار: فرصت‌های زمین مشارکت در ساخت\n• پرتفوی نمونه ما: در کنیاآلتی، زمین‌هایی با ضریب ساخت بالا و حق ساخت 7 طبقه، به مساحت 800 m² داریم که بستری ایده‌آل برای پروژه‌های مشارکت در ساخت‌اند.\n• مزیت:\n\nبه لطف زیرساخت در حال توسعه منطقه، کیفیت زندگی بالا و تقاضای رو به افزایش برای مسکن، می‌توانید پتانسیل پروژه خود را به حداکثر برسانید و پروژه‌های مسکونی مدرن با سود بالا توسعه دهید.\n\nبرای صاحبان زمین: ارزیابی مشارکت در ساخت\n\nزمین دارید اما نمی‌دانید چطور درست‌ترین و مطمئن‌ترین پیمانکار را پیدا کنید؟\n• زمین‌های شما را با قوی‌ترین و معتبرترین شرکت‌های ساختمانی منطقه، بر پایه منفعت متقابل و با قراردادهایی با پشتوانه حقوقی محکم آشنا می‌کنیم.\n• برای نسبت‌های تقسیم و مدل‌های پروژه‌ای که ارزش زمین شما را به حداکثر برسانند، می‌توانید با ما تماس بگیرید.\n\nپروژه‌های تبدیل شهری و شراکت در راه‌حل\n\nساختمان‌ها و مجتمع‌های قدیمی، پرخطر یا رسیده به پایان عمر اقتصادی شما در کنیاآلتی و اطراف آن، فرایندهای تبدیل شهری را از ابتدا تا انتها مدیریت می‌کنیم.\n• پل ارتباطی میان صاحبان حق و شرکت‌های پیمانکار هستیم و تهیه قراردادهای عادلانه و سودآور را تضمین می‌کنیم.\n• برای چند برابر کردن ارزش ملک فعلی شما با مفاهیم مدرن، مقاوم در برابر زلزله* و لوکس، مشاوره حرفه‌ای ارائه می‌دهیم.\n\nمزایای زیرساخت و موقعیت\n\nمکان‌های موجود در پرتفوی ما دارای همه امکانات زیرساختی مانند راه، آب، برق و فاضلاب هستند، وضعیت کاربری آن‌ها روشن است و از نظر موقعیت در پویاترین نقاط آنتالیا قرار دارند.\n\nچرا باید با ما کار کنید؟\n\n> ما فقط یک دفتر املاک نیستیم؛ با کادر متخصص خود که منطقه را خوب می‌شناسد و از دل ساخت‌وساز آمده، فرایندی سازمانی را مدیریت می‌کنیم که از حقوق هم پیمانکاران و هم مالکان ملک محافظت می‌کند.\n\n برای اطلاعات بیشتر، ارائه پرتفوی و فرصت‌های همکاری همین حالا پیام بدهید یا تماس بگیرید\n• «هپسی‌املاک در مورد مقاوم بودن این ملک در برابر زلزله هیچ تعهدی نمی‌تواند بدهد. برای اطلاعات بیشتر لطفاً با صاحب آگهی صحبت کنید.»","features":[],"auto":true,"sourceHash":"c5617e5dcf649465"}}},{"id":"c79cb39f-4914-4f33-a0f5-ad76a83dabd0","translations":{"en":{"title":"Land-for-flats plot for projects in central Konyaaltı","description":"A land-for-flats alternative in the Konyaaltı area, with high signage value and highly suitable for producing a modern-concept project. The floor-area ratio and floor-share ratios in the area will be assessed only with referenced, corporate contractor firms in an office setting. A representative location is marked.","features":[],"auto":true,"sourceHash":"8f6c684711850495"},"fa":{"title":"زمین پروژه‌ای مشارکت در ساخت در مرکز کنیاآلتی","description":"در منطقه کنیاآلتی، گزینه مشارکت در ساخت با ارزش تابلوی بالا که برای تولید پروژه با مفهوم مدرن بسیار مناسب است. ضریب ساخت و نسبت‌های تقسیم طبقات در این منطقه فقط با شرکت‌های پیمانکار سازمانی دارای سابقه و مرجع، در محیط دفتر بررسی خواهد شد. موقعیت به‌صورت نمادین علامت‌گذاری شده است.","features":[],"auto":true,"sourceHash":"8f6c684711850495"}}},{"id":"e52e6ba3-ce4b-47d1-af1c-2d494c4ae4c5","translations":{"en":{"title":"Prime land-for-flats plot in Muratpaşa","description":"A land-for-flats project site within the boundaries of Muratpaşa that will quickly recoup construction costs and has quick-sale potential. Due to landowners' request and corporate confidentiality, details will not be given by phone or message; serious contractor firms are invited to our office.","features":[],"auto":true,"sourceHash":"7858e9d82e767a28"},"fa":{"title":"زمین مشارکت در ساخت با قیمت ویژه (کوپن) در مورات‌پاشا","description":"در محدوده مورات‌پاشا، منطقه پروژه مشارکت در ساخت که هزینه‌های ساخت را در مدت کوتاهی مستهلک می‌کند و قابلیت فروش سریع دارد. به دلیل درخواست صاحبان زمین و محرمانگی سازمانی، جزئیات از طریق تلفن یا پیام داده نخواهد شد؛ شرکت‌های پیمانکار جدی به دفتر ما دعوت هستند.","features":[],"auto":true,"sourceHash":"7858e9d82e767a28"}}},{"id":"1e353739-9c57-44ef-94b8-e54521a86293","translations":{"en":{"title":"4+1 villa with garden and private pool in Altınkale","description":"A 4+1 villa in Altınkale with 466 m² gross and 350 m² net usable area. A VRF air-conditioning system, underfloor heating, sauna and hammam complete the private pool and garden. To get information about garden use, land share and current sale terms, or to arrange an on-site presentation, you can speak with İshak Kahraman.","features":["Private pool","Garden","Underfloor heating","VRF air conditioning","Sauna","Hammam","Outdoor parking"],"auto":true,"sourceHash":"d7a62fba0ca4845f"},"fa":{"title":"ویلای 4+1 با باغ و استخر اختصاصی در آلتین‌قلعه","description":"ویلای 4+1 در آلتین‌قلعه با فضای ناخالص 466 m² و فضای قابل استفاده خالص 350 m². استخر اختصاصی و باغ را سیستم کولر VRF، گرمایش از کف، سونا و حمام ترکی کامل می‌کنند. برای اطلاع درباره استفاده از باغ، سهم زمین و شرایط فروش روز یا هماهنگی ارائه حضوری می‌توانید با ایشاک کهرمان صحبت کنید.","features":["استخر اختصاصی","باغ","گرمایش از کف","کولر VRF","سونا","حمام ترکی","پارکینگ روباز"],"auto":true,"sourceHash":"d7a62fba0ca4845f"}}},{"id":"4a7e7823-51e9-4c88-ae23-6e40db6c6395","translations":{"en":{"title":"4+1 in Arapsuyu offering airy living spaces","description":"A 4+1 apartment on the second floor of a two-storey building in Arapsuyu Mahallesi. With 250 m² gross and 240 m² net area, three bathrooms, a balcony, a combi boiler and outdoor parking, it offers a spacious living arrangement. It is currently tenanted. You can speak with our consultant for the current sale price and rental terms.","features":["Balcony","Combi boiler","Outdoor parking","Three facades","Tenanted"],"auto":true,"sourceHash":"96186866d07ba24e"},"fa":{"title":"آپارتمان 4+1 با فضاهای زندگی جادار در آراپسویو","description":"در محله آراپسویو، آپارتمان 4+1 در طبقه دوم یک ساختمان دوطبقه. با 250 m² ناخالص و 240 m² خالص، سه حمام، بالکن، پکیج و پارکینگ روباز، چیدمان زندگی بزرگی ارائه می‌دهد. وضعیت استفاده: دارای مستأجر است. برای قیمت فروش روز و شرایط اجاره می‌توانید با مشاور ما صحبت کنید.","features":["بالکن","پکیج","پارکینگ روباز","سه نما","دارای مستأجر"],"auto":true,"sourceHash":"96186866d07ba24e"}}},{"id":"e2e10a7a-6103-46a6-be3a-3e2f66e5a537","translations":{"en":{"title":"3+1 villa with private pool and garden in Çamyuva","description":"A furnished 3+1 villa with a garden and private pool in Çamyuva. The amount of 95.000 TL per month is a long-term option offered on the condition of annual rent paid in advance. You can contact our consultant for information on short-term accommodation, daily or weekly prices and availability.","features":["Private pool","Detached garden","Furnished","Air conditioning","Outdoor parking","Annual rent paid in advance"],"auto":true,"sourceHash":"ccba51c68e70873e"},"fa":{"title":"ویلای 3+1 با استخر اختصاصی و باغ در چام‌یووا","description":"ویلای 3+1 مبله با باغ و استخر اختصاصی در چام‌یووا. مبلغ ماهیانه 95.000 TL گزینه اجاره بلندمدت با شرط پرداخت پیش‌پرداخت یک‌ساله است. برای اطلاع از اقامت کوتاه‌مدت، قیمت روزانه یا هفتگی و موجودی می‌توانید با مشاور ما تماس بگیرید.","features":["استخر اختصاصی","باغ مستقل","مبله","کولر","پارکینگ روباز","شرط اجاره یک‌ساله پیش‌پرداخت"],"auto":true,"sourceHash":"ccba51c68e70873e"}}},{"id":"46f64e00-1108-45a3-848a-fcfc64e7135b","translations":{"en":{"title":"Spacious 3+2 duplex in Yeni Emek","description":"A 3+2 duplex apartment on the upper floor of a two-storey building in Yeni Emek Mahallesi. With 200 m² gross and 190 m² net usable area, three bathrooms and a balcony, it offers a spacious layout suited to family life. You can speak with our consultant about the current sale terms and an on-site presentation of this apartment, which has a combi boiler and three facades.","features":["Duplex","Balcony","Combi boiler","Three facades","Vacant"],"auto":true,"sourceHash":"381b73b9fb9ed26f"},"fa":{"title":"دوبلکس 3+2 جادار و بزرگ در ینی‌امک","description":"در محله ینی‌امک، آپارتمان دوبلکس 3+2 در طبقه بالای یک ساختمان دوطبقه. با 200 m² ناخالص و 190 m² خالص فضای قابل استفاده، سه حمام و بالکن، چیدمان بزرگ مناسب زندگی خانوادگی ارائه می‌دهد. برای شرایط فروش روز و ارائه حضوری این آپارتمان پکیج‌دار سه‌نما می‌توانید با مشاور ما صحبت کنید.","features":["دوبلکس","بالکن","پکیج","سه نما","خالی"],"auto":true,"sourceHash":"381b73b9fb9ed26f"}}},{"id":"4508ba65-bd82-43fd-9f58-b79f5ed63181","translations":{"en":{"title":"Office for rent in a plaza on Atatürk Bulvarı","description":"An office with a 1+1 usage plan inside a plaza on Atatürk Bulvarı in Öğretmenevleri Mahallesi. The second-floor office, with 60 m² gross and 55 m² net area, is air-conditioned. Monthly rent is 35.000 TL. You can speak with our consultant for an on-site presentation, current availability and terms of use.","features":["In a plaza","Air conditioning","1+1 usage plan","Atatürk Bulvarı","Vacant"],"auto":true,"sourceHash":"064b728570908295"},"fa":{"title":"دفتر کار اجاره‌ای داخل پلازا در بلوار آتاتورک","description":"دفتر کار با پلان 1+1 داخل پلازا در بلوار آتاتورک محله اؤیرتمن‌اولری. این دفتر در طبقه دوم، با 60 m² ناخالص و 55 m² خالص، کولر دارد. اجاره ماهیانه 35.000 TL است. برای ارائه حضوری، موجودی روز و شرایط استفاده می‌توانید با مشاور ما صحبت کنید.","features":["داخل پلازا","کولر","پلان 1+1","بلوار آتاتورک","خالی"],"auto":true,"sourceHash":"064b728570908295"}}},{"id":"6256b4bb-db63-497b-b575-1dce5209f279","translations":{"en":{"title":"2.000 m² warehouse for rent with offices in Altınova","description":"A warehouse for rent with 2.000 m² gross area in Sinan Mahallesi, Altınova. With a transformer, fire detection and extinguishing system, office areas and an entrance suitable for loading and unloading, it offers a solution for business needs. Monthly rent is 375.000 TL. You can get in touch to inspect the technical features and rental terms on site.","features":["Office areas","Transformer","Fire system","Loading area","Suitable for vehicle entry"],"auto":true,"sourceHash":"2430866609cc1970"},"fa":{"title":"انبار 2.000 m² اجاره‌ای با دفتر در آلتینووا","description":"انبار اجاره‌ای با 2.000 m² فضای ناخالص در محله سینان آلتینووا. با ترانس برق، سیستم تشخیص و اطفای حریق، فضاهای اداری و ورودی مناسب بارگیری و تخلیه، راه‌حلی برای نیازهای کسب‌وکار ارائه می‌دهد. اجاره ماهیانه 375.000 TL است. برای بررسی حضوری مشخصات فنی و شرایط اجاره می‌توانید تماس بگیرید.","features":["فضاهای اداری","ترانس برق","سیستم اطفای حریق","محل بارگیری","مناسب ورود خودرو"],"auto":true,"sourceHash":"2430866609cc1970"}}},{"id":"63f2cb4d-50f2-4f78-b9ca-6874daa2f86a","translations":{"en":{"title":"Land-for-flats and renewal portfolios in Antalya","description":"This is a call for discussions about land-for-flats and urban renewal portfolios in Konyaaltı, Muratpaşa, Döşemealtı and Kepez. The 10.000 m² and Hurma location in the source should not be interpreted as a single definite parcel. No numerical sale price is stated. You can contact the consultant for closed portfolios and cooperation.","features":["Land-for-flats discussion","Urban renewal","Closed portfolio","Price on request"],"auto":true,"sourceHash":"099dd10b7680b97f"},"fa":{"title":"پرتفوی‌های مشارکت در ساخت و تبدیل شهری در آنتالیا","description":"این آگهی دعوت به گفتگو درباره پرتفوی‌های مشارکت در ساخت و تبدیل شهری در مناطق کنیاآلتی، مورات‌پاشا، دوشمه‌آلتی و کپز است. 10.000 m² و موقعیت هورما که در منبع ذکر شده نباید به‌عنوان یک قطعه قطعی واحد تفسیر شود. قیمت فروش عددی ذکر نشده است. برای پرتفوی‌های بسته و همکاری می‌توانید با مشاور تماس بگیرید.","features":["گفتگوی مشارکت در ساخت","تبدیل شهری","پرتفوی بسته","قیمت با مذاکره"],"auto":true,"sourceHash":"099dd10b7680b97f"}}}]$ka$::jsonb) d) t
where l.id = t.id;
